const money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value);
const compact=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:1}).format(value);
const percent=value=>(100*value).toFixed(1)+'%';
const valid=(point,frontier)=>point.tested===true&&point.simulationCount===frontier.simulationCount&&Number.isInteger(point.age)&&Number.isFinite(frontierAmount(frontier,point))&&frontierAmount(frontier,point)>=0&&Number.isFinite(point.readiness)&&point.readiness>=frontier.targetReadiness;
export const frontierAmount=(frontier,point)=>frontier?.kind==='savings'?point?.annualSavings:point?.annualSpending;
const escape=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function frontierUi(frontier){const claiming=frontier?.kind==='claiming',savings=frontier?.kind==='savings';return {claiming,savings,kind:savings?'savings':claiming?'claiming':'retirement',prefix:savings?'savings-frontier':claiming?'claim-frontier':'frontier',ageLabel:claiming?'Your Social Security claiming age':'Your retirement age',selectionLabel:claiming?'Select a tested Social Security claiming age':'Select a tested retirement age',valueLabel:claiming?'Claiming age':'Age',amountLabel:savings?'Annual personal savings · starting now':'Annual base spending · today’s dollars',amountShort:savings?'annual personal savings':'annual base spending',action:savings?'apply-savings-frontier-target':claiming?'apply-claim-frontier-target':'apply-frontier-target',button:savings?'Use selected age &amp; annual savings':claiming?'Use selected claiming age &amp; spending':'Use selected age &amp; spending'};}

export const frontierChoices=frontier=>(frontier?.points||[]).filter(point=>valid(point,frontier));
export function selectedFrontierPoint(frontier,index=0){const choices=frontierChoices(frontier);return choices[Math.max(0,Math.min(choices.length-1,Math.round(Number(index))||0))];}
export function frontierSelection(frontier,index){
  const point=selectedFrontierPoint(frontier,index);if(!point)return '';
  const ui=frontierUi(frontier);
  return `<dl class="frontier-values"><div><dt>${ui.ageLabel}</dt><dd>${point.age}</dd></div><div><dt>${ui.amountLabel}</dt><dd>${money(frontierAmount(frontier,point))}</dd></div><div><dt>Modeled readiness for this pair</dt><dd>${percent(point.readiness)}</dd></div></dl><p class="form-note">${point.atSearchLimit?`The search reached its ${money(ui.savings?frontier.savingsSearchLimit:frontier.spendingSearchLimit)} ${ui.savings?'savings':'spending'} limit; ${ui.savings?'higher savings':'higher amounts'} were not tested. `:''}This selection changes your ${ui.claiming?'Social Security claiming age':'retirement date'} and ${ui.savings?'personal savings':'base spending'} together. Run the full forecast after applying it.</p>${ui.savings?`<ul class="form-note">${(frontier.allocation||[]).map(entry=>`<li>${escape(entry.label)}: ${money(point.annualSavings*entry.share)} / year</li>`).join('')}</ul>`:''}`;
}
export function frontierPlot(frontier,index=0){
  const choices=frontierChoices(frontier),selected=selectedFrontierPoint(frontier,index);if(!selected)return '';
  const ui=frontierUi(frontier),width=760,height=360,left=82,right=26,top=35,bottom=52,w=width-left-right,h=height-top-bottom;
  const first=frontier.searchStartAge,last=frontier.searchEndAge,ageSpan=Math.max(1,last-first),maximum=Math.max(500,...choices.map(point=>frontierAmount(frontier,point)))*1.1;
  const x=age=>left+(age-first)/ageSpan*w,y=spending=>top+h-spending/maximum*h;
  const horizontal=Array.from({length:5},(_,i)=>{const value=maximum*i/4,py=y(value);return `<line x1="${left}" y1="${py}" x2="${left+w}" y2="${py}" class="frontier-grid"/><text x="${left-10}" y="${py+5}" text-anchor="end">${compact(value)}</text>`;}).join('');
  const interval=Math.max(1,Math.ceil(ageSpan/8)),ticks=[first,...Array.from({length:Math.floor(ageSpan/interval)},(_,i)=>first+(i+1)*interval),last];
  const vertical=[...new Set(ticks)].map(age=>`<text x="${x(age)}" y="${top+h+24}" text-anchor="middle">${age}</text>`).join('');
  const points=choices.map((point,i)=>`<circle cx="${x(point.age)}" cy="${y(frontierAmount(frontier,point))}" r="${point===selected?7:4}" class="frontier-point${point===selected?' selected':''}" data-frontier-index="${i}" data-frontier-kind="${ui.kind}"><title>${ui.valueLabel} ${point.age}: ${money(frontierAmount(frontier,point))} ${ui.amountShort}, ${percent(point.readiness)} modeled readiness · ${point.simulationCount} paths tested</title></circle>`).join('');
  return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${Math.round(frontier.targetReadiness*100)} percent readiness ${ui.savings?'annual savings':'spending'} targets. ${ui.claiming?'Social Security claiming age':'Age'} on the horizontal axis; ${ui.savings?'annual personal savings starting now':'annual base spending in today’s dollars'} on the vertical axis. Only tested pairs are plotted. Selected age ${selected.age}, ${ui.savings?'savings':'spending'} ${money(frontierAmount(frontier,selected))}."><text x="${left}" y="19">${ui.amountLabel}</text>${horizontal}${vertical}<line x1="${x(selected.age)}" y1="${top}" x2="${x(selected.age)}" y2="${top+h}" class="frontier-selection-line"/><line x1="${left}" y1="${y(frontierAmount(frontier,selected))}" x2="${left+w}" y2="${y(frontierAmount(frontier,selected))}" class="frontier-selection-line"/>${points}<text x="${left+w/2}" y="${height-6}" text-anchor="middle">${ui.ageLabel}</text></svg>`;
}
export function frontierCard(frontier,index=0,busy=false){
  if(!frontier)return '';
  const ui=frontierUi(frontier),choices=frontierChoices(frontier),point=selectedFrontierPoint(frontier,index),selectedIndex=Math.max(0,choices.indexOf(point));
  const title=`${Math.round(frontier.targetReadiness*100)}% readiness${ui.savings?' · age &amp; annual savings':ui.claiming?' · Social Security claiming age &amp; spending':' targets'}`,count=frontier.simulationCount.toLocaleString('en-US');
  return `<section class="card readiness-frontier"><h2>${title}</h2><p>Choose ${ui.claiming?'a Social Security claiming age':'a retirement age'} and ${ui.savings?'annual savings':'spending'} amount tested together with ${count} paths. Your saved plan changes when you apply the selection.</p>${ui.savings?`<p class="form-note">Annual base spending stays at ${money(frontier.fixedAnnualSpending)} in today’s dollars. Savings are your first-year deposits, rounded up to $500; your existing annual contribution growth rates continue. Employer contributions and spouse savings stay fixed. Check contribution limits and affordability before applying. Existing account proportions are retained; if no savings were entered, new deposits go to cash. ${frontier.alreadyRetired?'This search is for a future retirement; your plan already marks you retired.':''}</p>`:''}${point?`<div class="frontier-plot" id="${ui.prefix}-plot">${frontierPlot(frontier,selectedIndex)}</div><div class="frontier-slider"><label for="${ui.prefix}-age">${ui.selectionLabel}</label><input id="${ui.prefix}-age" data-frontier-slider="${ui.kind}" type="range" min="0" max="${choices.length-1}" step="1" value="${selectedIndex}" aria-valuetext="${ui.valueLabel} ${point.age}, ${money(frontierAmount(frontier,point))} ${ui.amountShort}" ${busy||choices.length===1?'disabled':''}></div><div id="${ui.prefix}-selection" aria-live="polite">${frontierSelection(frontier,selectedIndex)}</div><div class="actions"><button class="primary" data-action="${ui.action}" ${busy?'disabled':''}>${ui.button}</button></div>`:`<p class="form-note">No tested age and ${ui.savings?'annual savings':'spending'} combination reached the readiness target in this adaptive search.</p>`}<p class="form-note frontier-search-note">Only completed, qualifying tests are plotted; no untested combinations are connected or selectable. Adaptive search: ${ui.savings?'lower qualifying savings amounts':'higher qualifying spending amounts'} may exist. Every selectable point meets the readiness target in this ${count}-path sample. ${frontier.alreadyRetired?'':frontier.searchEndAge<frontier.searchStartAge?`No future whole-year ${ui.claiming?'Social Security claiming':'retirement'} ages were available to test.`:`${ui.claiming?'Claiming ages':'Retirement ages'} ${frontier.searchStartAge} through ${frontier.searchEndAge} were searched.`}</p></section>`;
}
